#!/usr/bin/env python3
"""Filter and aggregate RFC-4180-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import math
import sys
from collections.abc import Sequence
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path


class CsvInsightsError(Exception):
    """An error that should be reported to the command-line user."""


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and optionally calculate grouped sums and averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", help="CSV file to analyze")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN", help="column used to group rows")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN", help="column to sum")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN", help="column to average")
    parser.add_argument(
        "--output", choices=("json", "csv"), default="json", help="output format (default: json)"
    )
    return parser


def validate_headers(headers: list[str]) -> None:
    if not headers:
        raise CsvInsightsError("input has no header row")
    empty_positions = [str(index) for index, name in enumerate(headers, start=1) if name == ""]
    if empty_positions:
        raise CsvInsightsError(
            "header names must be non-empty (empty header at column "
            + ", ".join(empty_positions)
            + ")"
        )
    seen: set[str] = set()
    duplicates: list[str] = []
    for name in headers:
        if name in seen and name not in duplicates:
            duplicates.append(name)
        seen.add(name)
    if duplicates:
        raise CsvInsightsError("header names must be unique (duplicate: " + ", ".join(duplicates) + ")")


def parse_filters(raw_filters: Sequence[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for expression in raw_filters:
        if "=" not in expression:
            raise CsvInsightsError(
                f"malformed filter {expression!r}; expected COLUMN=VALUE"
            )
        column, value = expression.split("=", 1)
        if column == "":
            raise CsvInsightsError(
                f"malformed filter {expression!r}; column name cannot be empty"
            )
        filters.append((column, value))
    return filters


def require_columns(headers: Sequence[str], columns: Sequence[str]) -> None:
    known = set(headers)
    for column in columns:
        if column not in known:
            raise CsvInsightsError(f"unknown column: {column!r}")


def read_filtered_rows(
    path: Path, raw_filters: Sequence[str], requested_columns: Sequence[str]
) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    filters = parse_filters(raw_filters)
    try:
        source = path.open("r", encoding="utf-8", newline="")
    except OSError as error:
        raise CsvInsightsError(f"cannot open {path}: {error.strerror or error}") from error

    try:
        with source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise CsvInsightsError("input has no header row") from None
            validate_headers(headers)
            require_columns(headers, [column for column, _ in filters] + list(requested_columns))

            rows: list[tuple[int, dict[str, str]]] = []
            for record_number, fields in enumerate(reader, start=2):
                if len(fields) != len(headers):
                    raise CsvInsightsError(
                        f"row {record_number} has {len(fields)} fields; expected {len(headers)}"
                    )
                row = dict(zip(headers, fields))
                if all(row[column] == value for column, value in filters):
                    rows.append((record_number, row))
            return headers, rows
    except csv.Error as error:
        line = getattr(reader, "line_num", 0)
        location = f" near physical line {line}" if line else ""
        raise CsvInsightsError(f"malformed CSV{location}: {error}") from error
    except UnicodeError as error:
        raise CsvInsightsError(f"input is not valid UTF-8: {error}") from error


def parse_decimal(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        raise CsvInsightsError(f"row {row_number}, column {column!r}: numeric value is blank")
    try:
        number = Decimal(value)
    except InvalidOperation as error:
        raise CsvInsightsError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        ) from error
    if not number.is_finite():
        raise CsvInsightsError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        )
    return number


def sum_exact(values: Sequence[Decimal]) -> Decimal:
    """Sum decimals with enough precision to avoid context-induced rounding."""
    if not values:
        return Decimal(0)
    fractional_places = max(max(-value.as_tuple().exponent, 0) for value in values)
    integer_places = max(max(value.adjusted() + 1, 0) for value in values)
    carry_places = len(str(len(values))) + 1
    with localcontext() as context:
        context.prec = max(28, fractional_places + integer_places + carry_places)
        return sum(values, Decimal(0))


def decimal_text(value: Decimal) -> str:
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    if text in ("-0", ""):
        return "0"
    return text


def aggregate_rows(
    rows: Sequence[tuple[int, dict[str, str]]],
    group_column: str,
    sum_column: str | None,
    avg_column: str | None,
) -> tuple[list[str], list[dict[str, str]]]:
    numeric_columns = list(dict.fromkeys(column for column in (sum_column, avg_column) if column))
    groups: dict[str, dict[str, list[Decimal]]] = {}
    for record_number, row in rows:
        group = groups.setdefault(row[group_column], {column: [] for column in numeric_columns})
        for column in numeric_columns:
            group[column].append(parse_decimal(row[column], record_number, column))

    output_headers = [group_column]
    if sum_column:
        output_headers.append(f"sum_{sum_column}")
    if avg_column:
        output_headers.append(f"avg_{avg_column}")

    output_rows: list[dict[str, str]] = []
    for group_value in sorted(groups):
        values_by_column = groups[group_value]
        result = {group_column: group_value}
        if sum_column:
            result[f"sum_{sum_column}"] = decimal_text(sum_exact(values_by_column[sum_column]))
        if avg_column:
            values = values_by_column[avg_column]
            total = sum_exact(values)
            integer_places = max(total.adjusted() + 1, 1)
            with localcontext() as context:
                context.prec = max(28, integer_places + 28)
                average = total / Decimal(len(values))
            result[f"avg_{avg_column}"] = decimal_text(average)
        output_rows.append(result)
    return output_headers, output_rows


def emit_json(rows: Sequence[dict[str, str]]) -> None:
    json.dump(rows, sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write("\n")


def emit_csv(headers: Sequence[str], rows: Sequence[dict[str, str]]) -> None:
    writer = csv.DictWriter(
        sys.stdout, fieldnames=headers, extrasaction="raise", lineterminator="\r\n"
    )
    writer.writeheader()
    writer.writerows(rows)


def run(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_column or args.avg_column):
        parser.error("--group-by requires --sum and/or --avg")

    requested = [
        column for column in (args.group_by, args.sum_column, args.avg_column) if column
    ]
    headers, numbered_rows = read_filtered_rows(Path(args.input), args.where, requested)

    if args.group_by:
        output_headers, output_rows = aggregate_rows(
            numbered_rows, args.group_by, args.sum_column, args.avg_column
        )
    else:
        output_headers = headers
        output_rows = [row for _, row in numbered_rows]

    if args.output == "json":
        emit_json(output_rows)
    else:
        emit_csv(output_headers, output_rows)
    return 0


def main() -> int:
    try:
        return run()
    except CsvInsightsError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
